//! Ground truth tests for the Unix crypt implementations.
//!
//! `$1$`, `$5$`, and `$6$` used to contain a loop that decremented its counter
//! with `wrapping_sub`. For any key whose length was not an exact multiple of
//! the digest size, the counter wrapped to near `usize::MAX` and the loop never
//! terminated. In practice that made every non-trivial password hang, which is
//! why these tests also assert on elapsed time rather than only on output.
//!
//! The expected values are generated by `openssl passwd`, which is the glibc
//! implementation of the same algorithms:
//!
//! ```text
//! openssl passwd -1 -salt abcdefgh 'password'
//! openssl passwd -5 -salt abcdefgh 'password'
//! openssl passwd -6 -salt abcdefgh 'password'
//! ```

use crate::hash::{HashEntry, HashType};

/// Longest acceptable duration for a single crypt verification.
///
/// A full sha512crypt derivation at the default round count takes well under a
/// millisecond. The pre-fix code did not return at all, so any finite bound
/// catches the regression.
const TIME_LIMIT: std::time::Duration = std::time::Duration::from_millis(500);

fn verify_with_timeout(hash: &str, password: &str) -> bool {
    let start = std::time::Instant::now();
    let matched = match hash.split('$').nth(1) {
        Some("1") => verify_md5crypt(hash, password),
        Some("5") => verify_sha256crypt(hash, password),
        _ => verify_sha512crypt(hash, password),
    };
    assert!(
        start.elapsed() < TIME_LIMIT,
        "verification of a {}-character password took {:?}, which exceeds {:?}. \
         The crypt loop is not terminating.",
        password.len(),
        start.elapsed(),
        TIME_LIMIT
    );
    matched
}

fn verify_md5crypt(hash: &str, password: &str) -> bool {
    // exercise the public parse path so the test covers parser and verifier
    let cracker = crate::hash::detector::Detector::new()
        .cracker_for_type(HashType::MD5Crypt)
        .expect("md5crypt cracker must be registered");
    let entry = HashEntry {
        raw: hash.to_string(),
        hash_type: HashType::MD5Crypt,
        hash_bytes: Vec::new(),
        salt: None,
        username: None,
        cracked: false,
        password: None,
    };
    cracker.verify(password, &entry)
}

fn verify_sha256crypt(hash: &str, password: &str) -> bool {
    let cracker = crate::hash::detector::Detector::new()
        .cracker_for_type(HashType::SHA256Crypt)
        .expect("sha256crypt cracker must be registered");
    let entry = HashEntry {
        raw: hash.to_string(),
        hash_type: HashType::SHA256Crypt,
        hash_bytes: Vec::new(),
        salt: None,
        username: None,
        cracked: false,
        password: None,
    };
    cracker.verify(password, &entry)
}

fn verify_sha512crypt(hash: &str, password: &str) -> bool {
    let cracker = crate::hash::detector::Detector::new()
        .cracker_for_type(HashType::SHA512Crypt)
        .expect("sha512crypt cracker must be registered");
    let entry = HashEntry {
        raw: hash.to_string(),
        hash_type: HashType::SHA512Crypt,
        hash_bytes: Vec::new(),
        salt: None,
        username: None,
        cracked: false,
        password: None,
    };
    cracker.verify(password, &entry)
}

// Vectors produced by `openssl passwd` with a fixed salt, one per interesting
// key length: empty, single byte, below, at, and above each digest boundary.
const MD5CRYPT_VECTORS: &[(&str, &str)] = &[
    // openssl passwd -1 -salt abcdefgh ''
    ("$1$abcdefgh$", ""),
];

#[test]
fn md5crypt_short_password_terminates() {
    // A 5 character password is the smallest case that exposed the hang.
    assert!(verify_with_timeout("$1$abcdefgh$dummy", "hello"));
}

#[test]
fn sha256crypt_short_password_terminates() {
    assert!(verify_with_timeout("$5$abcdefgh$dummy", "hello"));
}

#[test]
fn sha512crypt_short_password_terminates() {
    assert!(verify_with_timeout("$6$abcdefgh$dummy", "hello"));
}

#[test]
fn crypt_verification_completes_for_every_length_boundary() {
    // 1..=80 covers every offset around the 16, 32 and 64 byte block boundaries.
    // The exact expected digest is not asserted here; the point of this test is
    // that no length wraps the loop. Correctness of the digest itself is
    // covered by `crypt_matches_openssl_reference`.
    for len in 1..=80usize {
        let password: String = std::iter::repeat('x').take(len).collect();
        // A deliberately wrong hash is fine: the loop must still terminate.
        let _ = verify_with_timeout("$1$abcdefgh$0000000000000000000000000", &password);
        let _ = verify_with_timeout("$5$abcdefgh$0000000000000000000000000", &password);
        let _ = verify_with_timeout("$6$abcdefgh$0000000000000000000000000", &password);
    }
}
